      const sha256=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(v=>v.toString(16).padStart(2,'0')).join('');
      assets[kind]={name:file.name,data:V.toBase64(bytes),sha256,size:bytes.length,dims:volume.dims,affine:volume.affine};state.sources.push({name:file.name,kind,sha256,at:new Date().toISOString(),accepted:volume.values.length,registered:true});
